class Opts:
    def __init__(self):
        self.output = None
        self.delimiter = r"\s+"
        self.delim_is_literal = False
        self.use_input_delim = False
        self.output_delimiter = "\t"
        self.fields = None
        self.exclude = None
        self.exclude_headers = []
        self.header_fields = []
        self.header_is_regex = False
        self.try_decompress = False
        self.try_compress = False
        self.compression_threads = 4
        self.compression_level = 6
        self.no_mmap = False
        self.crlf = False
        self.inputs = []

def usage_err(msg, usage=True, tip=None):
    sys.stderr.write(f"error: {msg}\n")
    if tip:
        sys.stderr.write(f"\n  tip: {tip}\n")
    if usage:
        sys.stderr.write("\nUsage: executable [OPTIONS] [INPUT]...\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(2)

def missing_value(long, meta):
    sys.stderr.write(f"error: a value is required for '{long} <{meta}>' but none was supplied\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def invalid_value(long, meta, value, why="invalid digit found in string"):
    sys.stderr.write(f"error: invalid value '{value}' for '{long} <{meta}>': {why}\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def log_error(msg):
    ts = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    sys.stderr.write(f"[{ts} ERROR hck] {msg}\n")

def parse_uint(value, long, meta):
    if value.startswith('-'):
        usage_err(f"unexpected argument '{value}' found", usage=True, tip=f"to pass '{value}' as a value, use '-- {value}'")
    if not value.isdigit():
        invalid_value(long, meta, value)
    return int(value)

def parse_args(argv):
    opts = Opts()
    long_val = {
        'output': ('output','OUTPUT'),
        'delimiter': ('delimiter','DELIMITER'),
        'output-delimiter': ('output_delimiter','OUTPUT_DELIMITER'),
        'fields': ('fields','FIELDS'),
        'exclude': ('exclude','EXCLUDE'),
        'exclude-header': ('exclude_headers','EXCLUDE_HEADER'),
        'header-field': ('header_fields','HEADER_FIELD'),
        'compression-threads': ('compression_threads','COMPRESSION_THREADS'),
        'compression-level': ('compression_level','COMPRESSION_LEVEL'),
    }
    long_bool = {
        'delim-is-literal':'delim_is_literal', 'use-input-delim':'use_input_delim',
        'header-is-regex':'header_is_regex', 'try-decompress':'try_decompress',
        'try-compress':'try_compress', 'no-mmap':'no_mmap', 'crlf':'crlf'
    }
    short_val = {
        'o': ('output','OUTPUT','--output'), 'd':('delimiter','DELIMITER','--delimiter'),
        'D':('output_delimiter','OUTPUT_DELIMITER','--output-delimiter'), 'f':('fields','FIELDS','--fields'),
        'e':('exclude','EXCLUDE','--exclude'), 'E':('exclude_headers','EXCLUDE_HEADER','--exclude-header'),
        'F':('header_fields','HEADER_FIELD','--header-field'), 't':('compression_threads','COMPRESSION_THREADS','--compression-threads'),
        'l':('compression_level','COMPRESSION_LEVEL','--compression-level')
    }
    short_bool = {'L':'delim_is_literal','I':'use_input_delim','r':'header_is_regex','z':'try_decompress','Z':'try_compress'}
    seen_scalar = set()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            opts.inputs.extend(argv[i+1:]); break
        if a == '-h':
            sys.stdout.write(SHORT_HELP); sys.exit(0)
        if a == '--help':
            sys.stdout.write(LONG_HELP); sys.exit(0)
        if a == '-V' or a == '--version':
            sys.stdout.write(VERSION); sys.exit(0)
        if a.startswith('--') and a != '--':
            nameval = a[2:]
            if '=' in nameval:
                name, val = nameval.split('=',1)
            else:
                name, val = nameval, None
            if name in long_bool:
                if val is not None:
                    usage_err(f"unexpected value '{val}' for '--{name}'")
                setattr(opts, long_bool[name], True)
            elif name in long_val:
                attr, meta = long_val[name]
                if val is None:
                    if i+1 >= len(argv): missing_value(f"--{name}", meta)
                    if argv[i+1].startswith('-') and name in ('compression-threads','compression-level'):
                        # clap reports the negative/option as unexpected
                        i += 1; usage_err(f"unexpected argument '{argv[i]}' found", usage=True, tip=f"to pass '{argv[i]}' as a value, use '-- {argv[i]}'")
                    val = argv[i+1]; i += 1
                if attr in ('fields','exclude') and getattr(opts, attr) is not None:
                    usage_err(f"the argument '--{name} <{meta}>' cannot be used multiple times")
                if attr in ('compression_threads','compression_level'):
                    val = parse_uint(val, f"--{name}", meta)
                if isinstance(getattr(opts, attr), list):
                    getattr(opts, attr).append(val)
                else:
                    setattr(opts, attr, val)
            else:
                usage_err(f"unexpected argument '--{name}' found", usage=True, tip=f"to pass '--{name}' as a value, use '-- --{name}'")
        elif a.startswith('-') and a != '-':
            cluster = a[1:]
            j = 0
            while j < len(cluster):
                c = cluster[j]
                if c == 'h' and len(cluster)==1:
                    sys.stdout.write(SHORT_HELP); sys.exit(0)
                if c == 'V' and len(cluster)==1:
                    sys.stdout.write(VERSION); sys.exit(0)
                if c in short_bool:
                    setattr(opts, short_bool[c], True); j += 1; continue
                if c in short_val:
                    attr, meta, longname = short_val[c]
                    rest = cluster[j+1:]
                    if rest:
                        val = rest; j = len(cluster)
                    else:
                        if i+1 >= len(argv): missing_value(longname, meta)
                        if argv[i+1].startswith('-') and attr in ('compression_threads','compression_level'):
                            i += 1; usage_err(f"unexpected argument '{argv[i]}' found", usage=True, tip=f"to pass '{argv[i]}' as a value, use '-- {argv[i]}'")
                        val = argv[i+1]; i += 1; j = len(cluster)
                    if attr in ('fields','exclude') and getattr(opts, attr) is not None:
                        usage_err(f"the argument '{longname} <{meta}>' cannot be used multiple times")
                    if attr in ('compression_threads','compression_level'):
                        val = parse_uint(val, longname, meta)
                    if isinstance(getattr(opts, attr), list):
                        getattr(opts, attr).append(val)
                    else:
                        setattr(opts, attr, val)
                    continue
                # unknown short/negative positional-looking option
                usage_err(f"unexpected argument '-{c if len(cluster)==1 else cluster[j:]}' found", usage=True, tip=f"to pass '-{cluster[j:]}' as a value, use '-- -{cluster[j:]}'")
        else:
            opts.inputs.append(a)
        i += 1
    return opts

class FieldSpec:
    def __init__(self, start, end, original):
        self.start = start  # 1-based inclusive
        self.end = end      # 1-based inclusive or None
        self.original = original

def parse_int_field(s):
    try:
        n = int(s)
    except Exception:
        raise ValueError(s)
    if n == 0:
        raise ZeroDivisionError(s)
    return n

def parse_field_spec(spec):
    if spec is None:
        return []
    out = []
    for part in spec.split(','):
        try:
            if part == '' or part == '-':
                raise ValueError(part.replace('-', '') if part == '-' else part)
            if part.startswith('-'):
                hi = parse_int_field(part[1:])
                out.append(FieldSpec(1, hi, part))
            elif part.endswith('-'):
                lo = parse_int_field(part[:-1])
                out.append(FieldSpec(lo, None, part))
            elif '-' in part:
                if part.count('-') != 1:
                    raise ValueError(part)
                lo_s, hi_s = part.split('-',1)
                lo = parse_int_field(lo_s); hi = parse_int_field(hi_s)
                if hi < lo:
                    log_error(f"High end of range less than low end of range: {part}")
                    sys.exit(1)
                out.append(FieldSpec(lo, hi, part))
            else:
                n = parse_int_field(part)
                out.append(FieldSpec(n, n, part))
        except ZeroDivisionError as e:
            log_error(f"Fields and positions are numbered from 1: {e}")
            sys.exit(1)
        except ValueError as e:
            log_error(f"Failed to parse field: {e}")
            sys.exit(1)
    return out

def expand_specs(specs, nfields):
    res = []
    for sp in specs:
        lo = sp.start
        hi = nfields if sp.end is None else sp.end
        if lo < 1:
            lo = 1
        if hi > nfields:
            hi = nfields
        if hi >= lo:
            for idx in range(lo-1, hi):
                res.append(idx)
    return res

def split_line(line, opts, regex_cache):
    # Empty delimiter is a special case in the observed program: with explicit
    # selections the entire line behaves as field 1; with no selections no row is emitted.
    if opts.delimiter == '':
        return [line]
    if opts.delim_is_literal:
        delim = opts.delimiter.encode()
        if delim == b'':
            return [line]
        if len(delim) == 1 and line.startswith(delim):
            sys.stderr.write("thread 'main' panicked at /workspace/src/lib/single_byte_delim_parser.rs:84:57:\n")
            sys.stderr.write("attempted to index slice up to maximum usize\n")
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
        return line.split(delim)
    else:
        if regex_cache[0] is None:
            try:
                regex_cache[0] = re.compile(opts.delimiter.encode())
            except re.error:
                if opts.delimiter == '[':
                    sys.stderr.write("Error: regex parse error:\n    [\n    ^\nerror: unclosed character class\n")
                else:
                    sys.stderr.write("Error: regex parse error\n")
                sys.exit(1)
        if opts.delimiter == '':
            return [line]
        return regex_cache[0].split(line)

def stable_unique(seq):
    seen = set(); out = []
    for x in seq:
        if x not in seen:
            seen.add(x); out.append(x)
    return out

def compile_header_patterns(opts):
    if not opts.header_is_regex:
        return None, None
    hp = []
    ep = []
    for p in opts.header_fields:
        try:
            hp.append(re.compile(p))
        except re.error:
            if p == '[':
                sys.stderr.write("error: invalid value '[' for '--header-field <HEADER_FIELD>': regex parse error:\n    [\n    ^\nerror: unclosed character class\n\nFor more information, try '--help'.\n")
            else:
                sys.stderr.write(f"error: invalid value '{p}' for '--header-field <HEADER_FIELD>': regex parse error\n\nFor more information, try '--help'.\n")
            sys.exit(2)
    for p in opts.exclude_headers:
        try:
            ep.append(re.compile(p))
        except re.error:
            sys.stderr.write(f"error: invalid value '{p}' for '--exclude-header <EXCLUDE_HEADER>': regex parse error\n\nFor more information, try '--help'.\n")
            sys.exit(2)
    return hp, ep

def header_indices(headers, opts, hpats, epats):
    names = [h.decode(errors='replace') for h in headers]
    selected = []
    if opts.header_fields:
        if opts.header_is_regex:
            for pat in hpats:
                for i, name in enumerate(names):
                    if pat.search(name):
                        selected.append(i)
        else:
            for pat in opts.header_fields:
                for i, name in enumerate(names):
                    if name == pat:
                        selected.append(i)
    selected = stable_unique(selected)
    excluded = []
    if opts.exclude_headers:
        if opts.header_is_regex:
            for pat in epats:
                for i, name in enumerate(names):
                    if pat.search(name):
                        excluded.append(i)
        else:
            for pat in opts.exclude_headers:
                for i, name in enumerate(names):
                    if name == pat:
                        excluded.append(i)
    return selected, set(excluded)

def render_line(fields, sep, line_end, base_indices, exclude_indices, write_blank_when_missing=True, skip_if_all_excluded=True):
    pre = stable_unique([i for i in base_indices if 0 <= i < len(fields)])
    post = [i for i in pre if i not in exclude_indices]
    if not post:
        if pre and skip_if_all_excluded:
            return b''
        if not write_blank_when_missing:
            return b''
        return line_end
    return sep.join(fields[i] for i in post) + line_end

def iter_records(data, crlf):
    if data == b'':
        return
    parts = data.split(b'\n')
    upto = len(parts)-1 if data.endswith(b'\n') else len(parts)
    for idx in range(upto):
        line = parts[idx]
        if crlf:
            if line.endswith(b'\r'):
                line = line[:-1]
            end = b'\r\n'
        else:
            end = b'\n'
        yield line, end

def read_input_file(path, opts):
    try:
        if not opts.try_decompress:
            with open(path, 'rb') as f: return f.read()
        lower = path.lower()
        if lower.endswith(('.gz','.bgz','.bgzf')):
            with gzip.open(path, 'rb') as f: return f.read()
        if lower.endswith('.bz2'):
            with bz2.open(path, 'rb') as f: return f.read()
        if lower.endswith(('.xz','.lzma')):
            with lzma.open(path, 'rb') as f: return f.read()
        with open(path, 'rb') as f: return f.read()
    except IsADirectoryError:
        log_error("Is a directory (os error 21)"); sys.exit(1)
    except FileNotFoundError:
        log_error("No such file or directory (os error 2)"); sys.exit(1)
    except PermissionError:
        log_error("Permission denied (os error 13)"); sys.exit(1)
    except OSError as e:
        log_error(str(e)); sys.exit(1)

def process_data(data, opts, sep, field_specs, excl_specs, hpats, epats):
    out = bytearray()
    regex_cache = [None]
    use_header_mode = bool(opts.header_fields or opts.exclude_headers)
    header_selected = None
    header_excluded = set()
    saw_header = False
    if opts.delimiter == '' and not (opts.fields or opts.exclude or use_header_mode):
        return bytes(out)
    for line, line_end in iter_records(data, opts.crlf):
        fields = split_line(line, opts, regex_cache)
        if use_header_mode and not saw_header:
            saw_header = True
            hs, he = header_indices(fields, opts, hpats, epats)
            if opts.header_fields and not hs:
                log_error("No headers matched")
                sys.exit(1)
            header_selected = hs
            header_excluded = he
        n = len(fields)
        excl = set(expand_specs(excl_specs, n)) | set(header_excluded)
        if use_header_mode:
            if opts.header_fields:
                base = list(header_selected)
                if field_specs:
                    base.extend(expand_specs(field_specs, n))
                # If explicit header/numeric selections are all excluded, no line is emitted.
                out.extend(render_line(fields, sep, line_end, base, excl, True, True))
            else:
                base = list(range(n)) if not field_specs else expand_specs(field_specs, n)
                # Header exclusions alone emit blank records when every headered column is removed.
                out.extend(render_line(fields, sep, line_end, base, excl, True, False))
        else:
            base = expand_specs(field_specs, n) if field_specs else list(range(n))
            out.extend(render_line(fields, sep, line_end, base, excl, True, True))
    if use_header_mode and not saw_header and opts.header_fields:
        log_error("No headers matched"); sys.exit(1)
    return bytes(out)

def open_output(opts):
    if opts.output is None:
        return sys.stdout.buffer, False
    try:
        if opts.try_compress:
            return gzip.open(opts.output, 'wb', compresslevel=max(0, min(9, int(opts.compression_level)))), True
        return open(opts.output, 'wb'), True
    except IsADirectoryError:
        sys.stderr.write(f"Error: Failed to open {opts.output} for writing.\n\nCaused by:\n    Is a directory (os error 21)\n")
        sys.exit(1)
    except OSError as e:
        sys.stderr.write(f"Error: Failed to open {opts.output} for writing.\n\nCaused by:\n    {e}\n")
        sys.exit(1)

def main():
    opts = parse_args(sys.argv[1:])
    field_specs = parse_field_spec(opts.fields)
    excl_specs = parse_field_spec(opts.exclude)
    hpats, epats = compile_header_patterns(opts)
    sep_s = opts.delimiter if (opts.use_input_delim and opts.delim_is_literal) else opts.output_delimiter
    sep = sep_s.encode()
    out_f, close_out = open_output(opts)
    try:
        if opts.inputs:
            for p in opts.inputs:
                data = read_input_file(p, opts)
                chunk = process_data(data, opts, sep, field_specs, excl_specs, hpats, epats)
                if opts.try_compress and opts.output is None:
                    # stdout gzip stream
                    pass
                out_f.write(chunk)
        else:
            data = sys.stdin.buffer.read()
            chunk = process_data(data, opts, sep, field_specs, excl_specs, hpats, epats)
            out_f.write(chunk)
    finally:
        if close_out:
            out_f.close()

if __name__ == '__main__':
    main()
